import inspect
from rich.repr import rich_repr

class AlwaysEqual:
    def __eq__(self, other):
        return True

@rich_repr
class MyClass:
    def __init__(self, a=AlwaysEqual()):
        self.a = a

def test_repr():
    obj = MyClass()
    # If the bug exists, rich_repr will think 'a' has no default value 
    # because AlwaysEqual() == inspect.Parameter.empty is True.
    # So it will just yield getattr(self, 'a'), which is AlwaysEqual().
    # If it worked correctly, it would yield ('a', AlwaysEqual(), AlwaysEqual()).

    # Let's see what auto_rich_repr yields.
    # We can't easily call auto_rich_repr because it's assigned to __rich_repr__.
    # But we can call __rich_repr__ on the instance.

    result = list(obj.__rich_repr__())
    print(f"Result: {result}")

    # Expected behavior: ('a', AlwaysEqual(), AlwaysEqual())
    # Buggy behavior: [AlwaysEqual()]

    assert len(result) == 1 and isinstance(result[0], tuple), f"Expected tuple for parameter with default, got {result}"

if __name__ == "__main__":
    try:
        test_repr()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
